    @FunctionalInterface interface Work {void run()throws Exception;}
    private static void check(boolean x,String m){if(!x)throw new AssertionError(m);}
    private static void eq(Object a,Object b){check(Objects.equals(a,b),"expected="+a+" actual="+b);}
    private static void run(String label,Work w){try{w.run();passed++;System.out.println("PASS "+label);}catch(Throwable e){failed++;System.out.println("FAIL "+label+": "+e.getClass().getSimpleName()+" "+e.getMessage());}}
    private static void rejects(int code,Work w)throws Exception{try{w.run();throw new AssertionError("expected "+code);}catch(Api.ApiException e){eq(code,e.code);}}
