        List<Person> people=List.of(new Person("0002","001",Set.of(),null,null,Set.of("AUTHOR","REVIEWER"),true),new Person("0003","001",Set.of(),null,null,Set.of("REVIEWER"),true),new Person("0004","002",Set.of(),null,null,Set.of("AUTHOR","REVIEWER"),true),new Person("0005","001",Set.of(),null,null,Set.of("READER"),true),new Person("0006","001",Set.of(),null,null,Set.of("PUBLISHER"),true),new Person("0007","001",Set.of(),null,null,Set.of("AUTHOR"),true));
        List<AccountBinding> bindings=new ArrayList<>();for(long id=2;id<=7;id++)bindings.add(new AccountBinding(id,String.format("%04d",id),true));
        return new Configuration("IDENTITY-"+(++identityVersion),new CodeRules("[0-9]{3}","[0-9]{4}","[A-Z]+"),Set.of("AUTHOR","REVIEWER","READER","PUBLISHER"),List.of(new Organization("001",null,true),new Organization("002",null,true)),people,List.of(new RoleRelations("AUTHOR",optional,optional),new RoleRelations("REVIEWER",optional,optional),new RoleRelations("READER",optional,optional),new RoleRelations("PUBLISHER",optional,optional)),bindings,grants);
