    private static void concurrentConfirm()throws Exception{long p=project("001");var b=confirmBody(p,prepare(p,"race","8"));ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Map<String,Object>>>f=new ArrayList<>();for(int i=0;i<2;i++)f.add(pool.submit(()->{start.await();return SurveySummaryImportsFormal.confirm(author,b);}));start.countDown();int replays=0;for(var job:f)if(Boolean.TRUE.equals(job.get(10,TimeUnit.SECONDS).get("replayed")))replays++;eq(1,replays);eq(1,records(p).size());}finally{start.countDown();pool.shutdownNow();pool.awaitTermination(5,TimeUnit.SECONDS);}}
